SELECT 'датчик тела контракта ' || fact_gap($1, 'contract-body') || ': назван ли требованием контракт — неизвестно' AS detail WHERE NOT fact_fresh($1, 'contract-body') UNION ALL SELECT f.name || ' — контракт его называет, а в наборе такого требования нет' FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'contract-body' AND NOT EXISTS (SELECT 1 FROM project_requirements r WHERE r.project_id = f.project_id AND r.id = f.name) ORDER BY 1
